create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),username varchar(32) not null unique,email varchar(254) not null unique,password_hash text not null,email_verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists roles(id uuid primary key default gen_random_uuid(),name text not null unique,description text);
create table if not exists permissions(id uuid primary key default gen_random_uuid(),name text not null unique);
create table if not exists user_roles(user_id uuid references users(id) on delete cascade,role_id uuid references roles(id) on delete cascade,primary key(user_id,role_id));
create table if not exists role_permissions(role_id uuid references roles(id) on delete cascade,permission_id uuid references permissions(id) on delete cascade,primary key(role_id,permission_id));
create table if not exists sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,token_hash char(64) not null unique,expires_at timestamptz not null,created_at timestamptz not null default now());
create index if not exists sessions_expiry_idx on sessions(expires_at);
create table if not exists nodes(id uuid primary key default gen_random_uuid(),name text not null unique,address text not null,status text not null default 'CONNECTING',wings_version text,docker_version text,cpu_percent numeric(5,2) default 0,ram_used_bytes bigint default 0,ram_total_bytes bigint default 0,disk_used_bytes bigint default 0,disk_total_bytes bigint default 0,last_heartbeat timestamptz,created_at timestamptz not null default now());
create table if not exists node_credentials(node_id uuid primary key references nodes(id) on delete cascade,secret_hash char(64) not null,created_at timestamptz not null default now());
create table if not exists allocations(id uuid primary key default gen_random_uuid(),node_id uuid not null references nodes(id) on delete cascade,ip inet not null,port integer not null check(port between 1 and 65535),server_id uuid,primary_for_server boolean not null default false,unique(node_id,ip,port));
create table if not exists eggs(id uuid primary key default gen_random_uuid(),name text not null unique,description text,author text,enabled boolean not null default true,created_at timestamptz not null default now());
create table if not exists egg_versions(id uuid primary key default gen_random_uuid(),egg_id uuid not null references eggs(id) on delete cascade,version text not null,docker_images jsonb not null default '[]',startup_command text not null,stop_command text,install_script text,environment jsonb not null default '{}',created_at timestamptz not null default now(),unique(egg_id,version));
create table if not exists servers(id uuid primary key default gen_random_uuid(),owner_id uuid not null references users(id),node_id uuid not null references nodes(id),primary_allocation_id uuid references allocations(id),egg_version_id uuid references egg_versions(id),name text not null,status text not null default 'INSTALLING',cpu_limit integer not null default 100,memory_limit bigint not null default 536870912,disk_limit bigint not null default 1073741824,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table allocations drop constraint if exists allocations_server_id_fkey;
alter table allocations add constraint allocations_server_id_fkey foreign key(server_id) references servers(id) on delete set null;
create index if not exists servers_owner_idx on servers(owner_id); create index if not exists servers_node_idx on servers(node_id);
create table if not exists server_variables(server_id uuid references servers(id) on delete cascade,key text not null,value text,primary key(server_id,key));
create table if not exists api_keys(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,name text not null,prefix text not null,secret_hash char(64) not null unique,scopes jsonb not null default '[]',expires_at timestamptz,last_used_at timestamptz,created_at timestamptz not null default now());
create table if not exists activity_logs(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete set null,action text not null,target_type text,target_id uuid,result text not null,ip inet,request_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists backups(id uuid primary key default gen_random_uuid(),server_id uuid not null references servers(id) on delete cascade,storage text not null,status text not null default 'QUEUED',size_bytes bigint,created_at timestamptz not null default now());
create table if not exists schedules(id uuid primary key default gen_random_uuid(),server_id uuid not null references servers(id) on delete cascade,name text not null,cron text not null,enabled boolean not null default true,next_run_at timestamptz,last_run_at timestamptz);
create table if not exists domains(id uuid primary key default gen_random_uuid(),name text not null unique,verification_status text not null default 'PENDING');
create table if not exists subdomains(id uuid primary key default gen_random_uuid(),domain_id uuid not null references domains(id) on delete cascade,label text not null,server_id uuid references servers(id) on delete set null,allocation_id uuid references allocations(id) on delete set null,unique(domain_id,label));
create table if not exists webhooks(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,name text not null,url text not null,secret_hash char(64) not null,events jsonb not null default '[]',enabled boolean not null default true);
create table if not exists webhook_deliveries(id uuid primary key default gen_random_uuid(),webhook_id uuid references webhooks(id) on delete cascade,event text not null,payload jsonb not null,status integer,attempts integer not null default 0,next_attempt_at timestamptz,created_at timestamptz not null default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id) on delete cascade,type text not null,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table if not exists free_node_policies(node_id uuid primary key references nodes(id) on delete cascade,max_servers integer not null default 10,max_cpu integer not null default 1000,max_ram_bytes bigint not null default 8589934592,max_disk_bytes bigint not null default 53687091200,claim_cooldown_seconds integer not null default 86400,server_lifetime_seconds integer,enabled boolean not null default false);
create table if not exists claims(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id),node_id uuid references nodes(id),server_id uuid references servers(id),status text not null,created_at timestamptz not null default now());
insert into roles(name) values ('Super Administrator'),('Administrator'),('Manager'),('Support'),('User') on conflict do nothing;
insert into permissions(name) values ('users.view'),('users.create'),('users.update'),('users.delete'),('nodes.view'),('nodes.create'),('nodes.update'),('nodes.delete'),('servers.view'),('servers.create'),('servers.update'),('servers.delete'),('servers.start'),('servers.stop'),('servers.restart'),('servers.kill'),('servers.reinstall'),('servers.transfer'),('files.view'),('files.upload'),('files.download'),('files.create'),('files.update'),('files.delete'),('backups.view'),('backups.create'),('backups.restore'),('backups.delete'),('databases.view'),('databases.create'),('databases.delete'),('domains.view'),('domains.create'),('domains.update'),('domains.delete'),('plugins.view'),('plugins.install'),('plugins.update'),('plugins.delete'),('system.view'),('system.update'),('system.settings') on conflict do nothing;
insert into role_permissions(role_id,permission_id) select r.id,p.id from roles r cross join permissions p where r.name='Super Administrator' on conflict do nothing;
